begin;

create table if not exists public.network_evidence_oracles (
  oracle_id uuid primary key default gen_random_uuid(), business_id uuid not null, oracle_name text not null,
  algorithm text not null check (algorithm in ('ED25519','ECDSA_P256_SHA256','RSA_PSS_SHA256','PGP')),
  public_key_fingerprint text not null check (public_key_fingerprint ~ '^[0-9A-Fa-f]{32,128}$'), public_key_reference text not null,
  status text not null default 'active' check (status in ('active','suspended','revoked')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (business_id, public_key_fingerprint)
);
create table if not exists public.network_oracle_evidence (
  evidence_id uuid primary key default gen_random_uuid(), oracle_id uuid not null references public.network_evidence_oracles(oracle_id), settlement_batch_id uuid references public.settlement_batches(id), route_id uuid references public.network_settlement_routes(route_id), manifest_id uuid references public.gcc_cross_border_manifests(manifest_id),
  evidence_type text not null check (evidence_type in ('ROUTE_INTEGRITY','LIQUIDITY_RESERVATION','CUSTOMS_CLEARANCE','POD_VERIFIED','FX_RATE','COUNTERPARTY_AUTHORIZATION','SETTLEMENT_AUTHORIZATION')),
  payload jsonb not null, payload_hash text not null check (payload_hash ~ '^[0-9a-f]{64}$'), signature text not null, signature_encoding text not null default 'base64' check (signature_encoding in ('base64','hex','armored')),
  issued_at timestamptz not null, expires_at timestamptz not null, nonce text not null check (length(nonce) between 16 and 256), verification_state text not null default 'submitted' check (verification_state in ('submitted','verified','rejected','expired')), verified_at timestamptz, verified_by text, verifier_attestation_hash text check (verifier_attestation_hash is null or verifier_attestation_hash ~ '^[0-9a-f]{64}$'), rejection_reason text, created_at timestamptz not null default now(),
  check (settlement_batch_id is not null or route_id is not null or manifest_id is not null), check (expires_at > issued_at), check ((verification_state = 'verified') = (verified_at is not null and verified_by is not null and verifier_attestation_hash is not null)), check (verification_state <> 'rejected' or rejection_reason is not null)
);
create table if not exists public.network_financial_finality_gates (
  gate_id uuid primary key default gen_random_uuid(), settlement_batch_id uuid not null unique references public.settlement_batches(id), route_id uuid unique references public.network_settlement_routes(route_id), state text not null default 'pending' check (state in ('pending','verified','blocked','expired','consumed')), evaluated_at timestamptz, consumed_at timestamptz, blocking_reason text, gate_hash text not null check (gate_hash ~ '^[0-9a-f]{64}$'), created_at timestamptz not null default now(), check ((state in ('verified','consumed')) = (blocking_reason is null))
);
create table if not exists public.network_financial_finality_requirements (
  requirement_id uuid primary key default gen_random_uuid(), gate_id uuid not null references public.network_financial_finality_gates(gate_id) on delete cascade, evidence_type text not null check (evidence_type in ('ROUTE_INTEGRITY','LIQUIDITY_RESERVATION','CUSTOMS_CLEARANCE','POD_VERIFIED','FX_RATE','COUNTERPARTY_AUTHORIZATION','SETTLEMENT_AUTHORIZATION')), required_count integer not null default 1 check (required_count > 0), created_at timestamptz not null default now(), unique (gate_id, evidence_type)
);
create table if not exists public.network_evidence_verification_events (
  event_id uuid primary key default gen_random_uuid(), evidence_id uuid not null references public.network_oracle_evidence(evidence_id), event_type text not null check (event_type in ('SUBMITTED','VERIFIED','REJECTED','EXPIRED')), payload jsonb not null default '{}'::jsonb, previous_hash text, event_hash text not null check (event_hash ~ '^[0-9a-f]{64}$'), created_by text not null, created_at timestamptz not null default now()
);
create index if not exists network_oracle_evidence_batch_idx on public.network_oracle_evidence(settlement_batch_id);
create index if not exists network_oracle_evidence_route_idx on public.network_oracle_evidence(route_id);
create index if not exists network_oracle_evidence_manifest_idx on public.network_oracle_evidence(manifest_id);
create index if not exists network_oracle_evidence_type_state_idx on public.network_oracle_evidence(evidence_type, verification_state, expires_at);
create index if not exists network_evidence_verification_events_evidence_idx on public.network_evidence_verification_events(evidence_id, created_at);

alter table public.network_evidence_oracles enable row level security; alter table public.network_oracle_evidence enable row level security; alter table public.network_financial_finality_gates enable row level security; alter table public.network_financial_finality_requirements enable row level security; alter table public.network_evidence_verification_events enable row level security;

drop policy if exists network_evidence_oracles_member_select on public.network_evidence_oracles;
create policy network_evidence_oracles_member_select on public.network_evidence_oracles for select to authenticated using (exists (select 1 from public.business_members bm where bm.business_id = network_evidence_oracles.business_id and bm.user_id = (select auth.uid())));
drop policy if exists network_oracle_evidence_member_select on public.network_oracle_evidence;
create policy network_oracle_evidence_member_select on public.network_oracle_evidence for select to authenticated using (exists (select 1 from public.network_evidence_oracles o join public.business_members bm on bm.business_id=o.business_id where o.oracle_id=network_oracle_evidence.oracle_id and bm.user_id=(select auth.uid())) or exists (select 1 from public.settlement_batches sb join public.business_members bm on bm.business_id in (sb.buyer_business_id,sb.seller_business_id) where sb.id=network_oracle_evidence.settlement_batch_id and bm.user_id=(select auth.uid())));
drop policy if exists network_financial_finality_gates_member_select on public.network_financial_finality_gates;
create policy network_financial_finality_gates_member_select on public.network_financial_finality_gates for select to authenticated using (exists (select 1 from public.settlement_batches sb join public.business_members bm on bm.business_id in (sb.buyer_business_id,sb.seller_business_id) where sb.id=network_financial_finality_gates.settlement_batch_id and bm.user_id=(select auth.uid())));
drop policy if exists network_financial_finality_requirements_member_select on public.network_financial_finality_requirements;
create policy network_financial_finality_requirements_member_select on public.network_financial_finality_requirements for select to authenticated using (exists (select 1 from public.network_financial_finality_gates g join public.settlement_batches sb on sb.id=g.settlement_batch_id join public.business_members bm on bm.business_id in (sb.buyer_business_id,sb.seller_business_id) where g.gate_id=network_financial_finality_requirements.gate_id and bm.user_id=(select auth.uid())));
drop policy if exists network_evidence_verification_events_member_select on public.network_evidence_verification_events;
create policy network_evidence_verification_events_member_select on public.network_evidence_verification_events for select to authenticated using (exists (select 1 from public.network_oracle_evidence e join public.network_evidence_oracles o on o.oracle_id=e.oracle_id join public.business_members bm on bm.business_id=o.business_id where e.evidence_id=network_evidence_verification_events.evidence_id and bm.user_id=(select auth.uid())));

revoke all on public.network_evidence_oracles, public.network_oracle_evidence, public.network_financial_finality_gates, public.network_financial_finality_requirements, public.network_evidence_verification_events from anon, authenticated, service_role;
grant select on public.network_evidence_oracles, public.network_oracle_evidence, public.network_financial_finality_gates, public.network_financial_finality_requirements, public.network_evidence_verification_events to authenticated, service_role;

create or replace function public.network_hash_evidence_event(p_evidence_id uuid,p_event_type text,p_payload jsonb,p_previous_hash text,p_created_by text,p_created_at timestamptz) returns text language sql immutable security invoker set search_path=pg_catalog, public, extensions, pg_temp as $$ select encode(extensions.digest(coalesce(p_previous_hash,'')||'|'||p_evidence_id::text||'|'||p_event_type||'|'||p_payload::text||'|'||coalesce(p_created_by,'')||'|'||p_created_at::text,'sha256'),'hex') $$;
create or replace function public.network_register_evidence_oracle(p_business_id uuid,p_oracle_name text,p_algorithm text,p_public_key_fingerprint text,p_public_key_reference text) returns uuid language plpgsql security definer set search_path=pg_catalog, public, extensions, pg_temp as $$ declare v_id uuid; begin if p_business_id is null or p_oracle_name is null or btrim(p_oracle_name)='' then raise exception 'invalid oracle registration'; end if; if p_algorithm not in ('ED25519','ECDSA_P256_SHA256','RSA_PSS_SHA256','PGP') then raise exception 'unsupported oracle algorithm'; end if; insert into public.network_evidence_oracles(business_id,oracle_name,algorithm,public_key_fingerprint,public_key_reference) values(p_business_id,btrim(p_oracle_name),p_algorithm,lower(p_public_key_fingerprint),p_public_key_reference) on conflict (business_id,public_key_fingerprint) do update set oracle_name=excluded.oracle_name,algorithm=excluded.algorithm,public_key_reference=excluded.public_key_reference,status='active',updated_at=now() returning oracle_id into v_id; return v_id; end; $$;
create or replace function public.network_submit_oracle_evidence(p_oracle_id uuid,p_settlement_batch_id uuid,p_route_id uuid,p_manifest_id uuid,p_evidence_type text,p_payload jsonb,p_signature text,p_signature_encoding text,p_issued_at timestamptz,p_expires_at timestamptz,p_nonce text) returns uuid language plpgsql security definer set search_path=pg_catalog, public, extensions, pg_temp as $$ declare v_id uuid; v_hash text; v_event_hash text; v_now timestamptz:=now(); begin perform 1 from public.network_evidence_oracles where oracle_id=p_oracle_id and status='active' for update; if not found then raise exception 'oracle unavailable'; end if; if p_payload is null or p_signature is null or p_nonce is null then raise exception 'evidence envelope incomplete'; end if; if p_expires_at<=p_issued_at then raise exception 'invalid evidence validity window'; end if; if p_expires_at<=v_now then raise exception 'evidence already expired'; end if; v_hash:=encode(extensions.digest(p_payload::text,'sha256'),'hex'); v_id:=gen_random_uuid(); insert into public.network_oracle_evidence(evidence_id,oracle_id,settlement_batch_id,route_id,manifest_id,evidence_type,payload,payload_hash,signature,signature_encoding,issued_at,expires_at,nonce) values(v_id,p_oracle_id,p_settlement_batch_id,p_route_id,p_manifest_id,p_evidence_type,p_payload,v_hash,p_signature,p_signature_encoding,p_issued_at,p_expires_at,p_nonce); v_event_hash:=public.network_hash_evidence_event(v_id,'SUBMITTED',jsonb_build_object('payload_hash',v_hash,'oracle_id',p_oracle_id),'service-role-boundary','service_role',v_now); insert into public.network_evidence_verification_events(evidence_id,event_type,payload,previous_hash,event_hash,created_by,created_at) values(v_id,'SUBMITTED',jsonb_build_object('payload_hash',v_hash,'verification_boundary','external_cryptographic_verifier'),'service-role-boundary',v_event_hash,'service_role',v_now); return v_id; end; $$;
create or replace function public.network_verify_oracle_evidence(p_evidence_id uuid,p_verification_result boolean,p_verifier_id text,p_verifier_attestation_hash text,p_reason text default null) returns text language plpgsql security definer set search_path=pg_catalog, public, extensions, pg_temp as $$ declare v_e public.network_oracle_evidence%rowtype; v_hash text; v_prev text; v_event_hash text; v_state text; v_now timestamptz:=now(); begin select * into v_e from public.network_oracle_evidence where evidence_id=p_evidence_id for update; if not found then raise exception 'evidence not found'; end if; if v_e.verification_state not in ('submitted','expired') then raise exception 'evidence is already terminal'; end if; v_hash:=encode(extensions.digest(v_e.payload::text,'sha256'),'hex'); if v_hash<>v_e.payload_hash then raise exception 'evidence payload hash mismatch'; end if; if p_verifier_id is null or btrim(p_verifier_id)='' then raise exception 'verifier identity required'; end if; if p_verifier_attestation_hash is null or p_verifier_attestation_hash !~ '^[0-9a-f]{64}$' then raise exception 'verifier attestation hash required'; end if; if v_e.expires_at<=v_now and p_verification_result then raise exception 'expired evidence cannot verify'; end if; v_state:=case when p_verification_result then 'verified' else 'rejected' end; update public.network_oracle_evidence set verification_state=v_state,verified_at=case when p_verification_result then v_now else null end,verified_by=case when p_verification_result then btrim(p_verifier_id) else null end,verifier_attestation_hash=case when p_verification_result then lower(p_verifier_attestation_hash) else null end,rejection_reason=case when not p_verification_result then coalesce(nullif(btrim(p_reason),''),'cryptographic verification rejected') else null end where evidence_id=p_evidence_id; select event_hash into v_prev from public.network_evidence_verification_events where evidence_id=p_evidence_id order by created_at desc,event_id desc limit 1; v_event_hash:=public.network_hash_evidence_event(p_evidence_id,case when p_verification_result then 'VERIFIED' else 'REJECTED' end,jsonb_build_object('payload_hash',v_hash,'verifier_id',btrim(p_verifier_id),'verifier_attestation_hash',lower(p_verifier_attestation_hash)),v_prev,btrim(p_verifier_id),v_now); insert into public.network_evidence_verification_events(evidence_id,event_type,payload,previous_hash,event_hash,created_by,created_at) values(p_evidence_id,case when p_verification_result then 'VERIFIED' else 'REJECTED' end,jsonb_build_object('payload_hash',v_hash,'verifier_id',btrim(p_verifier_id),'verifier_attestation_hash',lower(p_verifier_attestation_hash)),v_prev,v_event_hash,btrim(p_verifier_id),v_now); return v_state; end; $$;
create or replace function public.network_create_financial_finality_gate(p_settlement_batch_id uuid,p_route_id uuid,p_required_evidence jsonb) returns uuid language plpgsql security definer set search_path=pg_catalog, public, extensions, pg_temp as $$ declare v_gate uuid; v_hash text; r record; begin perform 1 from public.settlement_batches where id=p_settlement_batch_id for update; if not found then raise exception 'settlement batch not found'; end if; if p_route_id is not null then perform 1 from public.network_settlement_routes where route_id=p_route_id and settlement_batch_id=p_settlement_batch_id for update; if not found then raise exception 'route does not belong to settlement batch'; end if; end if; perform pg_advisory_xact_lock(hashtextextended('v38-gate:'||p_settlement_batch_id::text,0)); v_hash:=encode(extensions.digest(p_settlement_batch_id::text||'|'||coalesce(p_route_id::text,'')||'|'||p_required_evidence::text,'sha256'),'hex'); insert into public.network_financial_finality_gates(settlement_batch_id,route_id,state,gate_hash) values(p_settlement_batch_id,p_route_id,'pending',v_hash) on conflict (settlement_batch_id) do update set route_id=excluded.route_id,state='pending',blocking_reason=null,evaluated_at=null,consumed_at=null,gate_hash=excluded.gate_hash returning gate_id into v_gate; delete from public.network_financial_finality_requirements where gate_id=v_gate; for r in select value->>'evidence_type' evidence_type,coalesce((value->>'required_count')::integer,1) required_count from jsonb_array_elements(p_required_evidence) where value->>'evidence_type' is not null loop insert into public.network_financial_finality_requirements(gate_id,evidence_type,required_count) values(v_gate,r.evidence_type,r.required_count); end loop; return v_gate; end; $$;
create or replace function public.network_evaluate_financial_finality_gate(p_gate_id uuid) returns text language plpgsql security definer set search_path=pg_catalog, public, extensions, pg_temp as $$ declare g public.network_financial_finality_gates%rowtype; r record; v_count integer; v_state text:='verified'; v_reason text; v_now timestamptz:=now(); begin select * into g from public.network_financial_finality_gates where gate_id=p_gate_id for update; if not found then raise exception 'finality gate not found'; end if; perform pg_advisory_xact_lock(hashtextextended('v38-gate:'||g.settlement_batch_id::text,0)); for r in select * from public.network_financial_finality_requirements where gate_id=p_gate_id order by evidence_type loop select count(*) into v_count from public.network_oracle_evidence e where e.evidence_type=r.evidence_type and e.verification_state='verified' and e.expires_at>v_now and (e.settlement_batch_id=g.settlement_batch_id or e.route_id=g.route_id); if v_count<r.required_count then v_state:='blocked'; v_reason:=format('missing verified evidence: %s (%s/%s)',r.evidence_type,v_count,r.required_count); exit; end if; end loop; update public.network_financial_finality_gates set state=v_state,evaluated_at=v_now,blocking_reason=case when v_state='blocked' then v_reason else null end where gate_id=p_gate_id; return v_state; end; $$;
create or replace function public.network_consume_financial_finality_gate(p_gate_id uuid) returns boolean language plpgsql security definer set search_path=pg_catalog, public, extensions, pg_temp as $$ declare v_state text; v_now timestamptz:=now(); begin perform pg_advisory_xact_lock(hashtextextended('v38-consume:'||p_gate_id::text,0)); select state into v_state from public.network_financial_finality_gates where gate_id=p_gate_id for update; if not found then raise exception 'finality gate not found'; end if; if v_state<>'verified' then raise exception 'financial finality gate is not verified'; end if; update public.network_financial_finality_gates set state='consumed',consumed_at=v_now where gate_id=p_gate_id and state='verified'; return true; end; $$;
create or replace function public.network_protect_evidence_immutability() returns trigger language plpgsql security invoker set search_path=pg_catalog, public, extensions, pg_temp as $$ begin raise exception 'network oracle evidence is immutable'; end; $$;
create or replace function public.network_protect_verification_event_immutability() returns trigger language plpgsql security invoker set search_path=pg_catalog, public, extensions, pg_temp as $$ begin raise exception 'network evidence verification events are immutable'; end; $$;
create or replace function public.network_protect_gate_requirement_immutability() returns trigger language plpgsql security invoker set search_path=pg_catalog, public, extensions, pg_temp as $$ begin raise exception 'financial finality requirements are immutable'; end; $$;
drop trigger if exists network_oracle_evidence_immutable on public.network_oracle_evidence; create trigger network_oracle_evidence_immutable before update or delete on public.network_oracle_evidence for each row execute function public.network_protect_evidence_immutability();
drop trigger if exists network_evidence_verification_events_immutable on public.network_evidence_verification_events; create trigger network_evidence_verification_events_immutable before update or delete on public.network_evidence_verification_events for each row execute function public.network_protect_verification_event_immutability();
drop trigger if exists network_finality_requirements_immutable on public.network_financial_finality_requirements; create trigger network_finality_requirements_immutable before update or delete on public.network_financial_finality_requirements for each row execute function public.network_protect_gate_requirement_immutability();
revoke execute on function public.network_register_evidence_oracle(uuid,text,text,text,text) from public,anon,authenticated; revoke execute on function public.network_submit_oracle_evidence(uuid,uuid,uuid,uuid,text,jsonb,text,text,timestamptz,timestamptz,text) from public,anon,authenticated; revoke execute on function public.network_verify_oracle_evidence(uuid,boolean,text,text,text) from public,anon,authenticated; revoke execute on function public.network_create_financial_finality_gate(uuid,uuid,jsonb) from public,anon,authenticated; revoke execute on function public.network_evaluate_financial_finality_gate(uuid) from public,anon,authenticated; revoke execute on function public.network_consume_financial_finality_gate(uuid) from public,anon,authenticated;
grant execute on function public.network_register_evidence_oracle(uuid,text,text,text,text) to service_role; grant execute on function public.network_submit_oracle_evidence(uuid,uuid,uuid,uuid,text,jsonb,text,text,timestamptz,timestamptz,text) to service_role; grant execute on function public.network_verify_oracle_evidence(uuid,boolean,text,text,text) to service_role; grant execute on function public.network_create_financial_finality_gate(uuid,uuid,jsonb) to service_role; grant execute on function public.network_evaluate_financial_finality_gate(uuid) to service_role; grant execute on function public.network_consume_financial_finality_gate(uuid) to service_role;
commit;